'use strict';
const Field={async init(){const section=document.createElement('section');section.id='field';section.className='field-workbench';section.innerHTML=`<div class="page-heading"><div><div class="eyebrow">MUSONOI · FIELD OPERATIONS</div><h1>移动现场工作台</h1><p>扫描识别、联网核对、明确提交。离线不自动记账。</p></div></div><div class="field-actions"><button class="button primary" id="field-scan">现场扫描中心</button><a class="button secondary" href="#inventory">库存查询</a><button class="button secondary" id="field-count">库存盘点</button><button class="button secondary" id="field-samples">取样检验</button><button class="button secondary" id="field-loads">车辆装车核验</button></div><div class="panel field-help"><h3>操作反馈</h3><p>已识别不等于已确认；正式写入必须收到服务器确认。没有相机权限时可手动输入编号，或识别本地二维码图片。</p><p>添加主屏幕需要受信任HTTPS（本机localhost例外）。可用时浏览器显示安装按钮；不支持安装的浏览器仍可使用网页。</p><button id="field-install" class="button secondary" hidden>添加到主屏幕</button><a class="button secondary" href="#dashboard">信息总览</a></div>`;document.querySelector('#inventory').before(section);$('field-scan').onclick=()=>Scan.open().catch(e=>notify(e.message));$('field-count').disabled=!Business.can('stocktake:read');$('field-count').onclick=()=>Control.stocktakes().catch(e=>notify(e.message));$('field-samples').disabled=!Business.can('sample:read');$('field-samples').onclick=()=>Flow.samples().catch(e=>notify(e.message));$('field-loads').disabled=!Business.can('load:read');$('field-loads').onclick=()=>Scan.open().then(async()=>{$('scan-kind').value='load';await Scan.tasks();}).catch(e=>notify(e.message));const b=document.createElement('a');b.href='#field';b.className='button secondary';b.textContent='现场作业';document.querySelector('.top-actions').prepend(b);let prompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e;$('field-install').hidden=false;});$('field-install').onclick=async()=>{if(prompt){await prompt.prompt();prompt=null;$('field-install').hidden=true;}};window.addEventListener('hashchange',()=>Scan.stop());if(location.hash==='#field')section.scrollIntoView();}};Field.init().catch(e=>notify(e.message));
